<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserFederatedIdentity\Infrastructure\Driver\Rest;

use Psr\Http\Message\ResponseInterface;
use Psr\Http\Message\ServerRequestInterface;
use Throwable;
use OpenApi\Attributes as OA;
use DateTime;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\Gateway\UserFederatedIdentityFilter;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\Gateway\UserFederatedIdentityCursor;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\UserFederatedIdentityAttributes;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Application\Usecase\List\UserFederatedIdentityListUsecase;
use Civi\Lughauth\Features\Access\User\Domain\UserRef;
use Civi\Lughauth\Features\Access\TenantLoginProvider\Domain\TenantLoginProviderRef;

class UserFederatedIdentityListController
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly UserFederatedIdentityListUsecase $listUsecase,
    ) {
    }
    #[OA\Get(
        path: "/api/access/user-federated-identities",
        tags: ["User federated identity"],
        description:"Create",
        responses: [
        new OA\Response(response: 201, description: "Ok", content: new OA\JsonContent(type: "object", ref:"#/components/schemas/UserFederatedIdentityApiListDTO")),
        new OA\Response(response: 422, description: "Constraint error"),
    ]
    )
    ]
    public function list(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $this->logDebug("List User federated identity");
        $span = $this->startSpan("List User federated identity");
        try {
            $params = $request->getQueryParams();
            $limit = filter_var($params['limit'] ?? 100, FILTER_VALIDATE_INT, ['options' => ['min_range' => 1]]);
            if ($limit === false) {
                $response->getBody()->write('{"error":"invalid_limit"}');
                return $response->withStatus(400)->withHeader('Content-Type', 'application/json');
            }
            $filter = new UserFederatedIdentityFilter(
                uids: isset($params['uid']) ? [$params['uid']] : (isset($params['uids']) ? explode(',', $params['uids']) : null),
                search: $params['search'] ?? null,
                subject: $params['subject'] ?? null,
                user: isset($params['user']) ? new UserRef($params['user']) : null,
                users: isset($params['users']) ? explode(",", $params['users']) : null,
                loginProvider: isset($params['login-provider']) ? new TenantLoginProviderRef($params['login-provider']) : null,
                loginProviders: isset($params['login-providers']) ? explode(",", $params['login-providers']) : null,
            );
            $cursor = new UserFederatedIdentityCursor(
                limit: $limit,
                sinceUid: $params['since-uid'] ?? null,
                sinceSubject: $params['since-subject'] ?? null,
                order: isset($params['order']) ? $this->extractOrder(explode(',', $params['order'])) : null,
            );
            $result = $this->listUsecase->list($filter, $cursor);
            $value = ['items' => array_map(fn (UserFederatedIdentityAttributes $item): UserFederatedIdentityApiDTO => $this->mapUserFederatedIdentity($request, $item), $result->values())];
            $nextLink = $result->hasNext() ? $this->nextLink($result->cursor(), $params) : null;
            if (null !== $nextLink) {
                $value['next'] = "?{$nextLink}";
            }
            $encoded = json_encode($value);
            $response->getBody()->write($encoded === false ? '' : $encoded);
            return $response->withStatus(200)
              ->withHeader('Content-Type', 'application/json');
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function extractOrder(array $order): array
    {
        $this->logDebug("Extract order for User federated identity");
        $span = $this->startSpan("Extract order for User federated identity");
        try {
            $mapped = [];
            foreach ($order as $ord) {
                if ($ord === 'subject-asc') {
                    $mapped[] = 'subjectAsc';
                }
                if ($ord === 'subject-desc') {
                    $mapped[] = 'subjectDesc';
                }
            }
            return $mapped;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function nextLink(?UserFederatedIdentityCursor $value, array $params): ?string
    {
        $this->logDebug("Check generic allow for User federated identity");
        $span = $this->startSpan("Generic allow for User federated identity");
        try {
            if (!$value) {
                return null;
            }
            $link = array_merge($params, [
                        'since-uid' => $value->sinceUid(),
                        'since-subject' => $value->sinceSubject(),
                    ]);
            return http_build_query(array_filter($link, fn (mixed $item): bool => null !== $item));
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    private function mapUserFederatedIdentity(ServerRequestInterface $request, UserFederatedIdentityAttributes $value): UserFederatedIdentityApiDTO
    {
        $this->logDebug("Map entity to output dto for User federated identity");
        $span = $this->startSpan("Map entity to output dto for User federated identity");
        try {
            $user = $value->getUser();
            $loginProvider = $value->getLoginProvider();
            $dto = new UserFederatedIdentityApiDTO();
            $dto->uid = $value->getUid();
            $dto->user = $user ? ['$ref' => $user->uid()] : null;
            $dto->loginProvider = $loginProvider ? ['$ref' => $loginProvider->uid()] : null;
            $dto->subject = $value->getSubject();
            $dto->createdAt = $value->getCreatedAt()?->format(DateTime::ATOM);
            $dto->version = $value->getVersion();
            return $dto;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
